import csv
import io


def parse_csv(raw_csv: str):
    text = raw_csv.lstrip("\ufeff")
    lines = text.splitlines(keepends=True)

    start = 0
    while start < len(lines):
        stripped = lines[start].strip()
        if not stripped or stripped.startswith("#"):
            start += 1
        else:
            break

    if start >= len(lines):
        return {"columns": [], "rows": []}

    reader = csv.reader(
        io.StringIO("".join(lines[start:]), newline=""),
        delimiter=",",
        quotechar='"',
        doublequote=True,
        strict=False,
    )

    records = iter(reader)
    try:
        header = next(records)
    except StopIteration:
        return {"columns": [], "rows": []}

    if not header:
        for record in records:
            if record:
                header = record
                break
        else:
            return {"columns": [], "rows": []}

    columns = list(header)
    width = len(columns)
    rows = []

    for record in records:
        if not record:
            continue
        if len(record) > width:
            record = record[:width - 1] + [",".join(record[width - 1:])] if width else record
        elif len(record) < width:
            record = record + [""] * (width - len(record))
        rows.append(list(record))

    return {"columns": columns, "rows": rows}
